mapper.select:
SELECT owner_user_id AS ownerUserId, revision
FROM ds_agent_skill
WHERE tenant_id = #{tenantId} AND id = #{id}

mapper.update:
UPDATE ds_agent_skill
SET state = 'published', published_revision = draft_revision, draft_revision = NULL,
    updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{id} AND owner_user_id = #{userId}
  AND draft_revision IS NOT NULL AND deleted_at IS NULL

UPDATE ds_agent_skill SET deleted_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{id} AND owner_user_id = #{userId}
  AND builtin = FALSE AND deleted_at IS NULL
